   1→//! V2 Connector trait and typed filter specifications.
   2→//!
   3→//! This module introduces a filter-driven connector abstraction that accepts
   4→//! typed `IndexTarget` specs instead of bare wallet addresses. It defines:
   5→//!
   6→//! - The `Connector` async trait with `backfill` and `stream` methods
   7→//! - `ConnectorCapabilities` describing what a connector supports
   8→//! - Typed filter spec structs parsed from `IndexTarget.filter_spec` JSONB
   9→//! - Validation helpers for target-connector compatibility
  10→
  11→use serde::{Deserialize, Serialize};
  12→use tokio::sync::mpsc;
  13→
  14→use crate::v2::{ChainFamily, IndexTarget, IngestionBatch, RawTransaction, TargetKind, TargetMode};
  15→
  16→// ---------------------------------------------------------------------------
  17→// Connector capabilities
  18→// ---------------------------------------------------------------------------
  19→
  20→/// Describes the capabilities of a specific connector implementation.
  21→#[derive(Debug, Clone)]
  22→pub struct ConnectorCapabilities {
  23→    /// Which target kinds this connector can handle.
  24→    pub supported_target_kinds: Vec<TargetKind>,
  25→    /// Which ingestion modes this connector supports.
  26→    pub supported_modes: Vec<TargetMode>,
  27→    /// The chain family this connector serves.
  28→    pub chain_family: ChainFamily,
  29→}
  30→
  31→impl ConnectorCapabilities {
  32→    /// Returns `true` if the connector supports the given target kind.
  33→    pub fn supports_target_kind(&self, kind: TargetKind) -> bool {
  34→        self.supported_target_kinds.contains(&kind)
  35→    }
  36→
  37→    /// Returns `true` if the connector supports the given mode.
  38→    pub fn supports_mode(&self, mode: TargetMode) -> bool {
  39→        match mode {
  40→            TargetMode::Both => {
  41→                self.supported_modes.contains(&TargetMode::Backfill)
  42→                    || self.supported_modes.contains(&TargetMode::Both)
  43→            }
  44→            _ => self.supported_modes.contains(&mode),
  45→        }
  46→    }
  47→
  48→    /// Returns `true` if the connector can service the given target.
  49→    pub fn can_service(&self, target: &IndexTarget) -> bool {
  50→        self.chain_family == target.chain_family && self.supports_target_kind(target.kind)
  51→    }
  52→}
  53→
  54→// ---------------------------------------------------------------------------
  55→// Connector trait
  56→// ---------------------------------------------------------------------------
  57→
  58→/// A filter-driven connector that accepts typed target specs for ingestion.
  59→///
  60→/// This replaces the wallet-only `ChainIngestor` trait. Each connector
  61→/// implementation serves one `ChainFamily` and declares which `TargetKind`s
  62→/// and `TargetMode`s it supports via `capabilities()`.
  63→///
  64→/// The control plane (orchestrator) is responsible for:
  65→/// - routing targets to the correct connector based on capabilities
  66→/// - coordinating backfill+stream when `mode = Both` across connectors
  67→/// - managing checkpoints and ingestion runs
  68→#[async_trait::async_trait]
  69→pub trait Connector: Send + Sync {
  70→    /// Declare what this connector can do.
  71→    fn capabilities(&self) -> ConnectorCapabilities;
  72→
  73→    /// Fetch historical data for a target.
  74→    ///
  75→    /// - `target`: the registered index target with its filter spec
  76→    /// - `cursor`: optional checkpoint cursor (opaque JSON from a previous run)
  77→    /// - `limit`: maximum number of raw transactions to return
  78→    ///
  79→    /// Returns an `IngestionBatch` containing raw transactions and an optional
  80→    /// updated cursor for the next call.
  81→    async fn backfill(
  82→        &self,
  83→        target: &IndexTarget,
  84→        cursor: Option<&serde_json::Value>,
  85→        limit: usize,
  86→    ) -> anyhow::Result<IngestionBatch>;
  87→
  88→    /// Open a real-time stream for a target.
  89→    ///
  90→    /// - `target`: the registered index target with its filter spec
  91→    /// - `cursor`: optional checkpoint cursor to resume from
  92→    ///
  93→    /// Returns a channel receiver that yields raw transactions as they arrive.
  94→    /// The background task is spawned internally; dropping the receiver stops it.
  95→    ///
  96→    /// Default implementation returns an error for connectors that only
  97→    /// support backfill.
  98→    async fn stream(
  99→        &self,
 100→        _target: &IndexTarget,
 101→        _cursor: Option<&serde_json::Value>,
 102→    ) -> anyhow::Result<mpsc::Receiver<RawTransaction>> {
 103→        anyhow::bail!(
 104→            "streaming not supported by this connector ({})",
 105→            self.capabilities().chain_family
 106→        )
 107→    }
 108→}
