 110→// ---------------------------------------------------------------------------
 111→// Typed filter specs
 112→// ---------------------------------------------------------------------------
 113→
 114→/// Wallet-specific filter (optional narrowing beyond the address).
 115→/// Per TARGET_MODEL.md Section 2.1.
 116→#[derive(Debug, Clone, Default, Serialize, Deserialize)]
 117→pub struct WalletFilterSpec {
 118→    /// Restrict downstream matches to specific assets.
 119→    #[serde(default, skip_serializing_if = "Vec::is_empty")]
 120→    pub asset_filter: Vec<String>,
 121→    /// Minimum amount threshold for matches.
 122→    #[serde(default, skip_serializing_if = "Option::is_none")]
 123→    pub min_amount: Option<String>,
 124→    /// Restrict to specific transfer directions.
 125→    #[serde(default, skip_serializing_if = "Vec::is_empty")]
 126→    pub directions: Vec<String>,
 127→}
 128→
 129→/// Contract-specific filter (EVM only).
 130→/// Per TARGET_MODEL.md Section 2.2.
 131→#[derive(Debug, Clone, Default, Serialize, Deserialize)]
 132→pub struct ContractFilterSpec {
 133→    /// ABI event signatures to filter (e.g. "Transfer(address,address,uint256)").
 134→    #[serde(default, skip_serializing_if = "Vec::is_empty")]
 135→    pub event_signatures: Vec<String>,
 136→    /// Additional topic-position filters.
 137→    #[serde(default, skip_serializing_if = "Option::is_none")]
 138→    pub topic_filters: Option<serde_json::Map<String, serde_json::Value>>,
 139→}
 140→
 141→/// Program-specific filter (Solana only).
 142→/// Per TARGET_MODEL.md Section 2.3.
 143→#[derive(Debug, Clone, Serialize, Deserialize)]
 144→pub struct ProgramFilterSpec {
 145→    /// Instruction discriminator bytes to match.
 146→    #[serde(default, skip_serializing_if = "Vec::is_empty")]
 147→    pub instruction_discriminators: Vec<String>,
 148→    /// Whether CPI invocations count as matches (default: true).
 149→    #[serde(default = "default_true")]
 150→    pub include_cpi: bool,
 151→}
 152→
 153→impl Default for ProgramFilterSpec {
 154→    fn default() -> Self {
 155→        Self {
 156→            instruction_discriminators: Vec::new(),
 157→            include_cpi: true,
 158→        }
 159→    }
 160→}
 161→
 162→fn default_true() -> bool {
 163→    true
 164→}
 165→
 166→/// Account-specific filter (primarily Solana).
 167→/// Per TARGET_MODEL.md Section 2.4.
 168→#[derive(Debug, Clone, Default, Serialize, Deserialize)]
 169→pub struct AccountFilterSpec {
 170→    /// Restrict to write-only or read-only references.
 171→    #[serde(default, skip_serializing_if = "Vec::is_empty")]
 172→    pub access_types: Vec<String>,
 173→    /// Informational: program that owns this account.
 174→    #[serde(default, skip_serializing_if = "Option::is_none")]
 175→    pub associated_program: Option<String>,
 176→}
 177→
 178→/// Topic-based filter (EVM only, address is null on the target).
 179→/// Per TARGET_MODEL.md Section 2.5.
 180→#[derive(Debug, Clone, Serialize, Deserialize)]
 181→pub struct TopicFilterSpec {
 182→    /// Up to 4 topic positions. Each is a hex string, null, or an array of hex strings.
 183→    pub topics: Vec<serde_json::Value>,
 184→    /// Optional contract address narrowing.
 185→    #[serde(default, skip_serializing_if = "Vec::is_empty")]
 186→    pub address_filter: Vec<String>,
 187→}
 188→
 189→/// Market-specific filter (Hyperliquid only).
 190→/// Per TARGET_MODEL.md Section 2.6.
 191→#[derive(Debug, Clone, Default, Serialize, Deserialize)]
 192→pub struct MarketFilterSpec {
 193→    /// Types of market data to fetch.
 194→    #[serde(default, skip_serializing_if = "Vec::is_empty")]
 195→    pub data_types: Vec<String>,
 196→    /// Minimum trade size (query-time filter).
 197→    #[serde(default, skip_serializing_if = "Option::is_none")]
 198→    pub min_size: Option<String>,
 199→}
 200→
 201→/// Pool-specific filter (EVM and Solana).
 202→/// Per TARGET_MODEL.md Section 2.7.
 203→#[derive(Debug, Clone, Default, Serialize, Deserialize)]
 204→pub struct PoolFilterSpec {
 205→    /// Informational protocol name.
 206→    #[serde(default, skip_serializing_if = "Option::is_none")]
 207→    pub protocol: Option<String>,
 208→    /// Informational token pair.
 209→    #[serde(default, skip_serializing_if = "Vec::is_empty")]
 210→    pub token_pair: Vec<String>,
 211→    /// Event types to match.
 212→    #[serde(default, skip_serializing_if = "Vec::is_empty")]
 213→    pub event_types: Vec<String>,
 214→}
 215→
 216→/// Protocol address entry within a protocol filter spec.
 217→#[derive(Debug, Clone, Serialize, Deserialize)]
 218→pub struct ProtocolAddress {
 219→    pub address: String,
 220→    pub role: String,
 221→    #[serde(default, skip_serializing_if = "Option::is_none")]
 222→    pub label: Option<String>,
 223→}
 224→
 225→/// Protocol-level filter (composite target spanning multiple addresses).
 226→/// Per TARGET_MODEL.md Section 2.8.
 227→#[derive(Debug, Clone, Serialize, Deserialize)]
 228→pub struct ProtocolFilterSpec {
 229→    /// Protocol identifier name.
 230→    pub name: String,
 231→    /// Network → list of address entries.
 232→    pub addresses: std::collections::HashMap<String, Vec<ProtocolAddress>>,
 233→}
 234→
 235→// ---------------------------------------------------------------------------
 236→// Typed filter extraction
 237→// ---------------------------------------------------------------------------
 238→
 239→/// A parsed, typed representation of an `IndexTarget`'s filter spec.
 240→#[derive(Debug, Clone)]
 241→pub enum TypedFilterSpec {
 242→    Wallet(WalletFilterSpec),
 243→    Contract(ContractFilterSpec),
 244→    Program(ProgramFilterSpec),
 245→    Account(AccountFilterSpec),
 246→    TopicFilter(TopicFilterSpec),
 247→    Market(MarketFilterSpec),
 248→    Pool(PoolFilterSpec),
 249→    Protocol(ProtocolFilterSpec),
 250→}
 251→
 252→/// Extract a typed filter spec from an `IndexTarget`.
 253→///
 254→/// - For target kinds where `filter_spec` is optional, returns a default spec
 255→///   when the field is `None`.
 256→/// - For target kinds where `filter_spec` is required (`topic_filter`,
 257→///   `protocol`), returns an error when the field is `None`.
 258→pub fn extract_filter_spec(target: &IndexTarget) -> anyhow::Result<TypedFilterSpec> {
 259→    match target.kind {
 260→        TargetKind::Wallet => {
 261→            let spec = match &target.filter_spec {
 262→                Some(v) => serde_json::from_value(v.clone())?,
 263→                None => WalletFilterSpec::default(),
 264→            };
 265→            Ok(TypedFilterSpec::Wallet(spec))
 266→        }
 267→        TargetKind::Contract => {
 268→            let spec = match &target.filter_spec {
 269→                Some(v) => serde_json::from_value(v.clone())?,
 270→                None => ContractFilterSpec::default(),
 271→            };
 272→            Ok(TypedFilterSpec::Contract(spec))
 273→        }
 274→        TargetKind::Program => {
 275→            let spec = match &target.filter_spec {
 276→                Some(v) => serde_json::from_value(v.clone())?,
 277→                None => ProgramFilterSpec::default(),
 278→            };
 279→            Ok(TypedFilterSpec::Program(spec))
 280→        }
 281→        TargetKind::Account => {
 282→            let spec = match &target.filter_spec {
 283→                Some(v) => serde_json::from_value(v.clone())?,
 284→                None => AccountFilterSpec::default(),
 285→            };
 286→            Ok(TypedFilterSpec::Account(spec))
 287→        }
 288→        TargetKind::TopicFilter => {
 289→            let v = target
 290→                .filter_spec
 291→                .as_ref()
 292→                .ok_or_else(|| anyhow::anyhow!("topic_filter target requires filter_spec"))?;
 293→            let spec: TopicFilterSpec = serde_json::from_value(v.clone())?;
 294→            Ok(TypedFilterSpec::TopicFilter(spec))
 295→        }
 296→        TargetKind::Market => {
 297→            let spec = match &target.filter_spec {
 298→                Some(v) => serde_json::from_value(v.clone())?,
 299→                None => MarketFilterSpec::default(),
 300→            };
 301→            Ok(TypedFilterSpec::Market(spec))
 302→        }
 303→        TargetKind::Pool => {
 304→            let spec = match &target.filter_spec {
 305→                Some(v) => serde_json::from_value(v.clone())?,
 306→                None => PoolFilterSpec::default(),
 307→            };
 308→            Ok(TypedFilterSpec::Pool(spec))
 309→        }
 310→        TargetKind::Protocol => {
 311→            let v = target
 312→                .filter_spec
 313→                .as_ref()
 314→                .ok_or_else(|| anyhow::anyhow!("protocol target requires filter_spec"))?;
 315→            let spec: ProtocolFilterSpec = serde_json::from_value(v.clone())?;
 316→            Ok(TypedFilterSpec::Protocol(spec))
 317→        }
 318→    }
 319→}
