 403→    #[test]
 404→    fn capabilities_supports_target_kind() {
 405→        let caps = ConnectorCapabilities {
 406→            supported_target_kinds: vec![TargetKind::Wallet, TargetKind::Contract],
 407→            supported_modes: vec![TargetMode::Backfill],
 408→            chain_family: ChainFamily::Evm,
 409→        };
 410→        assert!(caps.supports_target_kind(TargetKind::Wallet));
 411→        assert!(caps.supports_target_kind(TargetKind::Contract));
 412→        assert!(!caps.supports_target_kind(TargetKind::Program));
 413→    }
 414→
 415→    #[test]
 416→    fn capabilities_supports_mode() {
 417→        let caps = ConnectorCapabilities {
 418→            supported_target_kinds: vec![TargetKind::Wallet],
 419→            supported_modes: vec![TargetMode::Backfill],
 420→            chain_family: ChainFamily::Evm,
 421→        };
 422→        assert!(caps.supports_mode(TargetMode::Backfill));
 423→        assert!(!caps.supports_mode(TargetMode::Stream));
 424→        // Both requires either Backfill or Both
 425→        assert!(caps.supports_mode(TargetMode::Both));
 426→    }
 427→
 428→    #[test]
 429→    fn capabilities_supports_mode_both() {
 430→        let caps = ConnectorCapabilities {
 431→            supported_target_kinds: vec![TargetKind::Wallet],
 432→            supported_modes: vec![TargetMode::Both],
 433→            chain_family: ChainFamily::Solana,
 434→        };
 435→        assert!(caps.supports_mode(TargetMode::Both));
 436→        // Both in the connector means it supports the combined mode
 437→    }
