        let json = serde_json::to_string(&batch).unwrap();
        let back: IngestionBatch = serde_json::from_str(&json).unwrap();
        assert_eq!(back.records.len(), 1);
        assert_eq!(back.records[0].network, "base-mainnet");
    }
}

