    // -----------------------------------------------------------------------

    fn make_target(
        kind: TargetKind,
        chain_family: ChainFamily,
        address: Option<&str>,
        filter_spec: Option<serde_json::Value>,
    ) -> IndexTarget {
        let now = Utc::now();
        IndexTarget {
            id: Uuid::new_v4(),
            kind,
            network: "hypercore-mainnet".to_string(),
